#define PEN_SIZE .02
#define BLUR_RADIUS 1

const vec4 background_color = vec4(1., .5, 1., 1.);
const vec4 pen_color = vec4(.5, .3, 0., 1.);

vec3 getNeighbor(ivec2 iCoord, int dx, int dy) {
    ivec2 pos = iCoord + ivec2(dx, dy);
    pos.x = clamp(pos.x, 0, int(iResolution.x) - 1);
    pos.y = clamp(pos.y, 0, int(iResolution.y) - 1);
    return texelFetch(iChannel0, pos, 0).xyz;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (iFrame == 0) {
        fragColor = background_color;
        return;
    }

    ivec2 iCoord = ivec2(fragCoord);
    float ratio = iResolution.x / iResolution.y;

    // apply transformations
    vec4 transformed;
    if (iFrame % 2 == 0) {
        // box blur
        vec3 col = vec3(0., 0., 0.);
        for (int dx = -BLUR_RADIUS; dx <= BLUR_RADIUS; dx++)
        for (int dy = -BLUR_RADIUS; dy <= BLUR_RADIUS; dy++)
            col += getNeighbor(iCoord, dx, dy);
        col /= pow(float(2 * BLUR_RADIUS + 1), 2.);
        transformed = vec4(col, 1.);
    }
    else {
        // sharpen
        vec3 col = texelFetch(iChannel0, iCoord, 0).xyz * 5.;
        for (int i = 0; i < 4; i++) {
            int dx = i % 2 == 0 ? 0 : i - 2;
            int dy = i % 2 == 0 ? i - 1 : 0;
            col -= getNeighbor(iCoord, dx, dy);
        }
        transformed = vec4(col, 1.);
        transformed.x = clamp(transformed.x, 0., 1.);
        transformed.y = clamp(transformed.y, 0., 1.);
        transformed.z = clamp(transformed.z, 0., 1.);
    }

    // edit color based on mouse position

    vec2 mouse_uv = iMouse.xy / iResolution.xy;
    vec2 uv = fragCoord / iResolution.xy;
    mouse_uv.x *= ratio;
    uv.x *= ratio;

    if (distance(mouse_uv, uv) < PEN_SIZE)
        fragColor = pen_color;
    else
        fragColor = transformed;
}
